<?php
declare(strict_types=1);namespace Atlas\Platform\Organizations\Rest;use Atlas\Platform\Core\Logging\Logger;use Atlas\Platform\Organizations\Onboarding\OrganizationOnboardingService;use InvalidArgumentException;use Throwable;final class OrganizationOnboardingController{public function __construct(private OrganizationOnboardingService$service,private Logger$logger){}public function permission():bool{return current_user_can('atlas_manage_organizations');}public function create(\WP_REST_Request$request):\WP_REST_Response|\WP_Error{$key=sanitize_text_field((string)$request->get_header('Idempotency-Key'));try{$result=$this->service->create($key,sanitize_text_field((string)$request->get_param('name')),sanitize_title((string)$request->get_param('slug')),get_current_user_id());return new \WP_REST_Response($result,$result['replayed']?200:201);}catch(InvalidArgumentException$failure){return new \WP_Error('atlas_invalid_organization',$failure->getMessage(),['status'=>400]);}catch(Throwable$failure){$conflict=str_contains($failure->getMessage(),'different request');$this->logger->log($conflict?'warning':'error','organizations.onboarding_failed','Organization onboarding did not complete.',['module'=>'organizations','exception'=>$failure]);return new \WP_Error('atlas_organization_onboarding_failed',$conflict?$failure->getMessage():'Organization onboarding failed safely.',['status'=>$conflict?409:500]);}}}
